r(population="North Pacific right whale (E Bering Sea)",region="SE Bering Sea",call_type="Upcall",shape="FM upsweep",f_start_hz=89,f_end_hz=153,freq_note="~90 -> ~150 Hz",duration_s=0.7,n_calls="436 (85% of 511 calls)",source="McDonald & Moore 2002 J Cetacean Res Manage 4:261",url="https://journal.iwc.int/index.php/jcrm/article/view/838",verification="abstract + Calderan 2021 table",notes="also down, constant and down-up calls (down-up unique to N Pacific) - no stats in abstract")
